source_raw_tex:
\eqalignno{\int_Hg\,d\nu
&=\int(g\times\chi H)d\nu\cr
\displaycause{131Fa}
&=\int J\times(g\times\chi H)\phi\,d\mu
=\int J\times g\phi\times\chi(\phi^{-1}[H])d\mu
=\int_{\phi^{-1}[H]}J\times g\phi\,d\mu\cr}

